import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {sourcePrefixHash} from '../live-paper/native-journal-restore.mjs';import {sha} from '../live-paper/native-dip-proof-v1.mjs';import {atomicJson} from '../execution/ledger.mjs';
const r=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),read=f=>JSON.parse(fs.readFileSync(f)),mode=process.argv[2];assert(['before','after'].includes(mode));const f='data/native-dip-host-preservation-20261004.json',prior=mode==='after'?read(f):null,banks={};
for(const type of ['baal-pair','no-maker','probability-receipt']){const activeFile=path.join(r,type+'-active.json'),active=read(activeFile),dir=path.join(r,type+'-cohorts',active.cohort),journal=path.join(dir,'journal.jsonl'),bytes=fs.statSync(journal).size,x={cohort:active.cohort,activeHash:sha(fs.readFileSync(activeFile)),bankHash:sha(fs.readFileSync(path.join(dir,'bank.json'))),journalBytes:bytes,journalPrefixHash:await sourcePrefixHash(journal,bytes)};
 if(prior){const old=prior.banks[type];assert.equal(x.activeHash,old.activeHash);assert.equal(x.bankHash,old.bankHash);assert(bytes>=old.journalBytes);assert.equal(await sourcePrefixHash(journal,old.journalBytes),old.journalPrefixHash);}banks[type]=x;}
const result={schemaVersion:1,at:new Date().toISOString(),banks,frozenBanksPreserved:true,originalJournalsPreserved:true,mode,feesChanged:false,competitionOrders:0};atomicJson(mode==='before'?f:'data/native-dip-host-preservation-after-20261004.json',result);console.log(JSON.stringify({mode,banks:Object.keys(banks),preserved:true}));
